import { useState, useEffect } from "react";
import InvoiceTable from "./InvoiceTable";

interface Invoice {
  id: number;
  number: string;
  customer: string;
  amount: number;
  status: "paid" | "pending" | "overdue";
}

const mockData: Invoice[] = [
  { id: 1, number: "INV-001", customer: "Acme Corp", amount: 450.00, status: "paid" },
  { id: 2, number: "INV-002", customer: "Beta Solutions", amount: 230.50, status: "pending" },
  { id: 3, number: "INV-003", customer: "Nexus Inc", amount: 890.25, status: "overdue" },
  { id: 4, number: "INV-004", customer: "Alpha Tech", amount: 150.75, status: "paid" },
  { id: 5, number: "INV-005", customer: "Global Partners", amount: 675.00, status: "pending" },
  { id: 6, number: "INV-006", customer: "Future Growth", amount: 320.00, status: "overdue" },
  { id: 7, number: "INV-007", customer: "Streamline Ltd", amount: 980.50, status: "paid" },
  { id: 8, number: "INV-008", customer: "Optima Group", amount: 400.25, status: "pending" },
];

export default function App() {
  const [invoices, setInvoices] = useState<Invoice[]>(mockData);
  const [sortConfig, setSortConfig] = useState<{ key: keyof Invoice; direction: "ascending" | "descending" | null }>({
    key: "amount",
    direction: "ascending",
  });

  useEffect(() => {
    // Mock data is already loaded
  }, []);

  const handleSort = (key: keyof Invoice) => {
    let direction: "ascending" | "descending" | null = "ascending";
    if (sortConfig.key === key && sortConfig.direction === "ascending") {
      direction = "descending";
    } else if (sortConfig.key === key && sortConfig.direction === "descending") {
      direction = "ascending";
    } else {
      direction = "ascending";
    }

    setSortConfig({ key, direction });
  };

  const sortedInvoices = [...invoices].sort((a, b) => {
    if (a[sortConfig.key] < b[sortConfig.key]) {
      return sortConfig.direction === "ascending" ? -1 : 1;
    }
    if (a[sortConfig.key] > b[sortConfig.key]) {
      return sortConfig.direction === "ascending" ? 1 : -1;
    }
    return 0;
  });

  const totalAmount = sortedInvoices.reduce((sum, invoice) => sum + invoice.amount, 0);

  return (
    <div className="container mx-auto p-6 max-w-6xl">
      <h1 className="text-2xl font-bold mb-6 text-gray-800">Invoices</h1>
      <InvoiceTable
        invoices={sortedInvoices}
        onSort={handleSort}
        sortConfig={sortConfig}
        totalAmount={totalAmount}
      />
    </div>
  );
}
