```tsx
import React from "react";
import { CheckIcon, ClockIcon, XIcon } from "lucide-react";

interface Invoice {
  id: number;
  number: string;
  customer: string;
  amount: number;
  status: "paid" | "pending" | "overdue";
}

interface StatusBadgeProps {
  status: "paid" | "pending" | "overdue";
}

interface InvoiceRowProps {
  invoice: Invoice;
  isTotal: boolean;
}

interface InvoiceTableProps {
  invoices: Invoice[];
  onSort: (key: keyof Invoice) => void;
  sortConfig: { key: keyof Invoice; direction: "ascending" | "descending" | null };
  totalAmount: number;
}

const StatusBadge: React.FC<StatusBadgeProps> = ({ status }) => {
  switch (status) {
    case "paid":
      return (
        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800">
          Paid
        </span>
      );
    case "pending":
      return (
        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-yellow-100 text-yellow-800">
          Pending
        </span>
      );
    case "overdue":
      return (
        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-800">
          Overdue
        </span>
      );
    default:
      return null;
  }
};

const InvoiceRow: React.FC<InvoiceRowProps> = ({ invoice, isTotal }) => {
  const statusColor = invoice.status === "paid" ? "text-green-600" : invoice.status === "pending" ? "text-yellow-600" : "text-red-600";

  return (
    <tr className={`hover:bg-gray-50 transition-colors ${isTotal ? "bg-gray-50 font-semibold" : ""}`}>
      <td className="px-4 py-3 border-b text-sm text-gray-700">{invoice.number}</td>
      <td className="px-4 py-3 border-b text-sm text-gray-700">{invoice.customer}</td>
      <td className="px-4 py-3 border-b text-sm text-gray-700 font-medium">
        ${invoice.amount.toFixed(2)}
      </td>
      <td className="px-4 py-3 border-b text-sm">
        <StatusBadge status={invoice.status} />
      </td>
    </tr>
  );
};

export const InvoiceTable: React.FC<InvoiceTableProps> = ({
  invoices,
  onSort,
  sortConfig,
  totalAmount,
}) => {
  const handleSortClick = (key: "number" | "customer" | "amount" | "status") => {
    onSort(key as keyof Invoice);
  };

  return (
    <div className="overflow-x-auto rounded-lg border border-gray-200 shadow-sm">
      <table className="min-w-full divide-y divide-gray-200">
        <thead className="bg-gray-50">
          <tr>
            <th
              className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer"
              onClick={() => handleSortClick("number")}
            >
              Number
            </th>
            <th
              className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer"
              onClick={() => handleSortClick("customer")}
            >
              Customer
            </th>
            <th
              className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer"
              onClick={() => handleSortClick("amount")}
            >
              Amount
            </th>
            <th
              className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer"
              onClick={() => handleSortClick("status")}
            >
              Status
            </th>
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-200">
          {invoices.map((invoice) => (
            <InvoiceRow
              key={invoice.id}
              invoice={invoice}
              isTotal={false}
            />
          ))}
          <tr className="bg-gray-50 font-semibold">
            <td className="px-4 py-3 border-b text-sm text-gray-700">
              Total
            </td>
            <td className="px-4 py-3 border-b text-sm text-gray-700" colSpan={2}>
              <span className="font-bold">${totalAmount.toFixed(2)}</span>
            </td>
            <td className="px-4 py-3 border-b text-sm"></td>
          </tr>
        </tbody>
      </table>
    </div>
  );
};
